// ============================================================================
//  Windowed statistics accumulator
// ============================================================================
struct Accum {
  uint32_t n;
  double   sum;
  double   sumsq;
  float    peak;

  void reset() { n = 0; sum = 0; sumsq = 0; peak = 0; }
  void add(float v) {
    n++;
    sum   += v;
    sumsq += (double)v * (double)v;
    float a = fabsf(v);
    if (a > peak) peak = a;
  }
  float rms()  const { return n ? sqrtf((float)(sumsq / n)) : 0.0f; }
  float mean() const { return n ? (float)(sum / n)          : 0.0f; }
};

